const b = $json.body ?? $json;
const allowed = new Set(['MAINTENANCE','HOUSEKEEPING','GUEST_REQUEST']);
const channel = String(b.channel || '').trim().toUpperCase();
const messageId = String(b.message_id || '').trim();
const intent = String(b.intent || '').trim().toUpperCase();
if (!channel) throw new Error('Missing required field: channel');
if (!messageId) throw new Error('Missing required field: message_id');
if (!allowed.has(intent)) throw new Error('Invalid intent');
if (!String(b.transcript || '').trim()) throw new Error('Missing transcript');
if ((intent === 'MAINTENANCE' || intent === 'HOUSEKEEPING') && !String(b.room_code || '').trim()) throw new Error('room_code is required for room work');
return [{ json: { idempotency_key: `${channel}:${messageId}`, channel, message_id: messageId, sender_id: b.sender_id ? String(b.sender_id) : null, intent, room_code: b.room_code ? String(b.room_code).trim() : null, transcript: String(b.transcript).trim(), summary: b.summary ? String(b.summary).trim() : null, priority: String(b.priority || 'NORMAL').toUpperCase() } }];

const result = $('Create Operational Task').item.json;
if (!result.id) throw new Error('Core did not return task id');
return [{ json: { ok: true, task: result, truth: 'CORE_TASK_CREATED' } }];
